"use strict";
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const KEY="globologiaPro.v1";
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const n=v=>{const x=Number(String(v??"").replace(",","."));return Number.isFinite(x)?x:0};
const clamp=(v,a,b)=>Math.min(b,Math.max(a,n(v)));
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const defaults={settings:{currency:"$",customCurrency:"",hourly:5000,km:450,minMargin:25,targetMargin:40,waste:5,contingency:5,rounding:1000,estimator:{perMeter:28,wallPerM2:65,types:{"Guirnalda orgánica":1,"Arco orgánico":1.08,"Medio arco":1,"Arco completo":1.12,"Columna":1.18,"Pared":1,"Bouquet":1},density:{Básica:.8,Media:1,Abundante:1.3},distribution:{'5"':25,'9"':25,'12"':38,'18"':9,'24"':3}}},materials:[],budgets:[]};
let db=load(), route="home", current=null, estimatorResult=null, activeLibrary="Todos";
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return merge(structuredClone(defaults),x||{})}catch{return structuredClone(defaults)}}
function merge(a,b){for(const k in b){if(b[k]&&typeof b[k]==="object"&&!Array.isArray(b[k]))a[k]=merge(a[k]||{},b[k]);else a[k]=b[k]}return a}
function persist(){localStorage.setItem(KEY,JSON.stringify(db))}
function money(v){const sym=db.settings.currency==="Otro"?(db.settings.customCurrency||"$"):db.settings.currency;return `${sym} ${Math.round(n(v)).toLocaleString("es-AR")}`}
function pct(v){return `${n(v).toLocaleString("es-AR",{maximumFractionDigits:1})}%`}
function modeLabel(m){return m==="Básico"?"Armado de presupuesto":m}
function toast(t){const el=$("#toast");el.textContent=t;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),2200)}
const help={bags:["Bolsas por color","Las bolsas se calculan por separado para cada color. El presupuesto incluye el precio completo de todas las bolsas necesarias."],consumed:["Costo consumido","Es el valor de los materiales que realmente usaste, aunque los hayas comprado anteriormente."],cash:["Desembolso","Es el dinero que necesitás sacar hoy para comprar lo que te falta."],stock:["Stock","Material que ya tenés. Usarlo no exige una compra hoy, pero igualmente tiene costo."],amortization:["Amortización","Reparte el precio de compra de un elemento recuperable entre todos sus usos estimados."],labor:["Mano de obra","El tiempo de diseñar, preparar, montar, desmontar y ordenar también es parte del costo."],waste:["Desperdicio","Cubre globos rotos, defectuosos, usados en pruebas o descartados durante el armado."],markup:["Recargo","Porcentaje que se suma al costo. Un recargo de 50% multiplica el costo por 1,5."],margin:["Margen","Porcentaje del precio que queda como ganancia. Un margen de 40% se calcula dividiendo el costo por 0,60."],breakeven:["Punto de equilibrio","Precio mínimo que cubre costos, comisiones e impuestos sin generar pérdida."],hourlyProfit:["Ganancia por hora","Ganancia real dividida por todas las horas efectivamente dedicadas al trabajo."]};
function H(k){return `<button class="help" data-help="${k}" aria-label="Ayuda">?</button>`}
const decoOptions=["Guirnalda orgánica","Arco","Medio arco","Columna","Bouquet","Pared de globos","Centro de mesa","Decoración personalizada","Otro"];
const field=(label,key,value="",type="number",span="")=>`<div class="field ${span}"><label>${label}</label><input type="${type}" data-field="${key}" value="${esc(value)}" ${type==="number"?'min="0" step="any"':""}></div>`;
const select=(label,key,value,opts,span="")=>`<div class="field ${span}"><label>${label}</label><select data-field="${key}">${opts.map(o=>`<option ${o===value?"selected":""}>${esc(o)}</option>`).join("")}</select></div>`;
function eventFields(x){return `<div class="section"><header><h2>Datos del evento</h2></header><div class="section-body grid">${field("Cliente","client",x.client,"text")}${field("Trabajo / referencia","name",x.name,"text")}${select("Tipo de decoración","type",x.type,decoOptions)}${field("Fecha del evento","eventDate",x.eventDate,"date")}${field("Lugar","place",x.place,"text","s6")}${field("Cantidad","quantity",x.quantity,"number","s3")}${select("Estado","status",x.status,["Borrador","Enviado","Confirmado","Realizado","Cancelado"],"s3")}${field("Horario de montaje","setupTime",x.setupTime,"time")}${field("Horario del evento","eventTime",x.eventTime,"time")}${field("Horario de desmontaje","teardownTime",x.teardownTime,"time")}${field("Descripción / observaciones","notes",x.notes,"text","s12")}</div></div>`}
const completeEventFields=eventFields;eventFields=x=>route==="budget"?completeEventFields(x):"";
function newBasic(){return{id:uid(),mode:"Básico",created:new Date().toISOString(),client:"",name:"",type:"Guirnalda orgánica",eventDate:"",place:"",quantity:1,status:"Borrador",setupTime:"",eventTime:"",teardownTime:"",notes:"",balloons:0,colors:1,colorRows:[{name:"Color 1",qty:0}],packPrice:0,packQty:100,prepHours:0,setupHours:0,teardownHours:0,hourly:db.settings.hourly,transportMode:"Fijo",transport:0,km:0,kmCost:db.settings.km,tolls:0,parking:0,waste:db.settings.waste,pricing:"Recargo",rate:50,extras:[],confirmedStock:false}}
function ensureBasicColors(x){const count=Math.max(1,Math.floor(n(x.colors)||1));if(!Array.isArray(x.colorRows)||!x.colorRows.length){const total=Math.max(0,Math.ceil(n(x.balloons))),base=Math.floor(total/count),rest=total%count;x.colorRows=Array.from({length:count},(_,i)=>({name:`Color ${i+1}`,qty:base+(i<rest?1:0)}))}while(x.colorRows.length<count)x.colorRows.push({name:`Color ${x.colorRows.length+1}`,qty:0});if(x.colorRows.length>count)x.colorRows=x.colorRows.slice(0,count);x.colors=count;x.balloons=x.colorRows.reduce((a,r)=>a+Math.max(0,Math.ceil(n(r.qty))),0);return x.colorRows}
function calcBasic(x){const rows=ensureBasicColors(x),packQty=Math.max(0,Math.floor(n(x.packQty))),unit=packQty?n(x.packPrice)/packQty:0,wasteRate=Math.max(0,n(x.waste)),details=rows.map((r,i)=>{const qty=Math.max(0,Math.ceil(n(r.qty))),reserve=Math.ceil(qty*wasteRate/100),needed=qty+reserve,packs=needed&&packQty?Math.ceil(needed/packQty):0,left=Math.max(0,packs*packQty-needed);return{name:r.name||`Color ${i+1}`,qty,reserve,needed,packs,left,cash:packs*n(x.packPrice),leftValue:left*unit}}),balloons=details.reduce((a,r)=>a+r.qty,0),reserve=details.reduce((a,r)=>a+r.reserve,0),needed=balloons+reserve,packs=details.reduce((a,r)=>a+r.packs,0),cash=details.reduce((a,r)=>a+r.cash,0),left=details.reduce((a,r)=>a+r.left,0),cons=balloons*unit,waste=reserve*unit,material=cash,labor=(n(x.prepHours)+n(x.setupHours)+n(x.teardownHours))*n(x.hourly),transport=x.transportMode==="Fijo"?n(x.transport):n(x.km)*n(x.kmCost)+n(x.tolls)+n(x.parking),extras=x.extras.reduce((a,e)=>a+n(e.amount),0),cost=material+extras+labor+transport,price=x.pricing==="Margen"?cost/(1-clamp(x.rate,0,99.9)/100):cost*(1+n(x.rate)/100),profit=price-cost;x.balloons=balloons;return{unit,balloons,colors:rows.length,details,reserve,needed,cons,waste,material,packs,cash,left,leftValue:left*unit,labor,transport,extras,cost,price,profit,margin:price?profit/price*100:0,hours:n(x.prepHours)+n(x.setupHours)+n(x.teardownHours)}}
function basicWarnings(x,c){const a=[];if(!c.labor)a.push("No cargaste mano de obra.");if(!c.transport)a.push("No cargaste traslado.");if(c.details.some(r=>!r.qty))a.push("Hay colores sin cantidad de globos.");if(c.packs&&c.left)a.push("El cálculo compra bolsas completas para cada color; el sobrante queda disponible para otros trabajos.");if(n(x.setupHours)&&!n(x.teardownHours))a.push("Hay montaje pero no cargaste desmontaje.");if(c.margin<db.settings.minMargin)a.push("El margen queda por debajo del mínimo configurado.");return a}
function renderBasic(){if(!current||current.mode!=="Básico")current=newBasic();ensureBasicColors(current);const x=current,c=calcBasic(x),colorRows=c.details.map((r,i)=>`<tr><td><input class="table-input wide" data-color-row="${i}" data-k="name" value="${esc(x.colorRows[i].name||`Color ${i+1}`)}" aria-label="Nombre del color ${i+1}"></td><td><input class="table-input" type="number" min="0" step="1" data-color-row="${i}" data-k="qty" value="${r.qty}" aria-label="Globos del color ${i+1}"></td><td>${r.reserve}</td><td><b>${r.packs}</b></td><td>${r.left}</td></tr>`).join("");app(`<div class="page-head"><div><p class="eyebrow">Presupuesto del trabajo</p><h1>Armado de presupuesto</h1><p>Desglosá los globos por color y calculá las bolsas y costos de la decoración.</p></div><button class="btn ghost" data-go="home">← Inicio</button></div><div class="workspace"><div class="form-stack">${eventFields(x)}<div class="section"><header><h2>Globos por color ${H("bags")}</h2><button class="btn small secondary" data-go-estimator>No sé cuántos necesito</button></header><div class="section-body"><div class="grid">${field("Cantidad de colores","colors",x.colors||1)}${field("Precio de cada bolsa","packPrice",x.packPrice)}${field("Globos por bolsa","packQty",x.packQty)}</div><div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>Color</th><th>Globos</th><th>Reserva</th><th>Bolsas</th><th>Sobrante</th></tr></thead><tbody>${colorRows}</tbody></table></div><div class="note" style="margin-top:14px"><b>${c.balloons} globos para el armado</b> · ${c.reserve} de reserva · ${c.packs} bolsa(s) en total · Sobran ${c.left} globos. Cada color se calcula por separado.</div></div></div><div class="section"><header><h2>Mano de obra ${H("labor")}</h2></header><div class="section-body grid">${field("Preparación (horas)","prepHours",x.prepHours)}${field("Montaje (horas)","setupHours",x.setupHours)}${field("Desmontaje (horas)","teardownHours",x.teardownHours)}${field("Valor por hora","hourly",x.hourly)}</div></div><div class="section"><header><h2>Traslado</h2><div class="segmented"><button data-set="transportMode" data-value="Fijo" class="${x.transportMode==="Fijo"?"active":""}">Costo fijo</button><button data-set="transportMode" data-value="Kilómetros" class="${x.transportMode==="Kilómetros"?"active":""}">Por km</button></div></header><div class="section-body grid">${x.transportMode==="Fijo"?field("Costo de traslado","transport",x.transport):field("Kilómetros ida y vuelta","km",x.km)+field("Costo por km","kmCost",x.kmCost)+field("Peajes","tolls",x.tolls)+field("Estacionamiento","parking",x.parking)}</div></div>${extrasSection(x)}<div class="section"><header><h2>Roturas y reserva ${H("waste")}</h2></header><div class="section-body grid">${field("Porcentaje estimado","waste",x.waste)}<div class="field s8"><div class="note">La reserva se calcula individualmente para cada color antes de determinar sus bolsas.</div></div></div></div><div class="section"><header><h2>Rentabilidad</h2></header><div class="section-body grid"><div class="field s6"><label>Método</label><div class="segmented"><button data-set="pricing" data-value="Recargo" class="${x.pricing==="Recargo"?"active":""}">Recargo ${H("markup")}</button><button data-set="pricing" data-value="Margen" class="${x.pricing==="Margen"?"active":""}">Margen ${H("margin")}</button></div></div>${field("Porcentaje","rate",x.rate,"number","s3")}</div></div>${warningSection(basicWarnings(x,c))}</div>${basicResult(x,c)}</div>`)}
function extrasSection(x){return `<div class="section"><header><h2>Otros materiales e insumos</h2><button class="btn small secondary" data-add-extra>+ Agregar</button></header><div class="section-body">${x.extras.length?`<div class="table-wrap"><table><thead><tr><th>Descripción</th><th>Importe</th><th></th></tr></thead><tbody>${x.extras.map((e,i)=>`<tr><td><input class="table-input wide" data-extra="${i}" data-k="name" value="${esc(e.name)}"></td><td><input class="table-input" type="number" data-extra="${i}" data-k="amount" value="${n(e.amount)}"></td><td><button class="btn small danger" data-del-extra="${i}">×</button></td></tr>`).join("")}</tbody></table></div>`:`<div class="empty">Todavía no agregaste otros insumos.</div>`}</div></div>`}
function warningSection(a){return `<div class="section"><header><h2>Revisá tu presupuesto</h2></header><div class="section-body warning-list">${a.length?a.map(v=>`<div class="warning">⚠ ${v}</div>`).join(""):`<div class="warning ok">✓ No encontramos omisiones evidentes.</div>`}</div></div>`}
function basicResult(x,c){return `<aside class="result-panel"><p class="eyebrow" style="color:#d8bd84">Tu presupuesto</p><h2>${esc(x.name)||"Nuevo trabajo"}</h2>${rr("Globos del armado",c.balloons+" globos",true)}${rr("Colores",c.colors,true)}${rr("Reserva por roturas",c.reserve+" globos",true)}${rr("Bolsas necesarias",c.packs,true)}${rr("Costo de las bolsas",c.material)}${rr("Otros materiales",c.extras)}${rr("Mano de obra",c.labor)}${rr("Traslado",c.transport)}${rr("Costo total",c.cost)}<div class="cash-box"><small>INVERSIÓN EN BOLSAS</small><strong>${money(c.cash)}</strong></div><div class="result-main"><small>Precio sugerido</small><strong>${money(c.price)}</strong></div>${rr("Ganancia estimada",c.profit)}${rr("Margen",pct(c.margin),true)}${rr("Globos sobrantes",`${c.left} · ${money(c.leftValue)}`,true)}<p style="font-size:.78rem;color:#c5d4d7;line-height:1.45">El presupuesto incluye las bolsas completas necesarias para cada color. Los globos sobrantes quedan disponibles para futuros trabajos.</p><div class="result-actions"><button class="btn primary" data-save>Guardar presupuesto</button><button class="btn secondary" data-client>Ver presupuesto para cliente</button><button class="btn secondary" data-profit-from>Analizar rentabilidad</button></div></aside>`}
function rr(label,val,raw=false){return `<div class="result-row"><span>${label}</span><strong>${raw?val:money(val)}</strong></div>`}
function newExpert(){return{id:uid(),mode:"Experto",created:new Date().toISOString(),client:"",name:"",type:"Guirnalda orgánica",eventDate:"",place:"",quantity:1,status:"Borrador",setupTime:"",eventTime:"",teardownTime:"",notes:"",balloonRows:[],otherRows:[],recoverables:[],labor:["Diseño / planificación","Preparación","Inflado y armado","Montaje en evento","Desmontaje","Limpieza / clasificación"].map(name=>({name,hours:0,rate:db.settings.hourly})),helpers:[],km:0,kmCost:db.settings.km,trips:1,tolls:0,parking:0,freight:0,transportOther:0,balloonWaste:db.settings.waste,generalWaste:0,contingencyType:"Porcentaje",contingency:db.settings.contingency,pricing:"Margen",rate:db.settings.targetMargin,rounding:db.settings.rounding,deposit:30,validity:10,confirmedStock:false}}
function calcRow(r){const unit=n(r.packQty)?n(r.packPrice)/n(r.packQty):n(r.unitPrice),used=n(r.used),stockUsed=Math.min(used,n(r.stock)),needed=Math.max(0,used-stockUsed),packs=r.packQty?Math.ceil(needed/n(r.packQty)):0,cash=packs*n(r.packPrice),left=Math.max(0,n(r.stock)-stockUsed+packs*n(r.packQty)-needed);return{unit,cons:used*unit,stockUsed,needed,packs,cash,left,leftValue:left*unit}}
function calcExpert(x){const balloons=x.balloonRows.map(calcRow),others=x.otherRows.map(calcRow),balloonConsumed=balloons.reduce((a,r)=>a+r.cons,0),otherConsumed=others.reduce((a,r)=>a+r.cons,0),recoverable=x.recoverables.reduce((a,r)=>a+recoverCost(r),0),labor=x.labor.reduce((a,r)=>a+n(r.hours)*n(r.rate),0),helpers=x.helpers.reduce((a,r)=>a+(r.type==="Fijo"?n(r.fixed):n(r.hours)*n(r.rate)),0),transport=n(x.km)*n(x.kmCost)*Math.max(1,n(x.trips))+n(x.tolls)+n(x.parking)+n(x.freight)+n(x.transportOther),waste=balloonConsumed*n(x.balloonWaste)/100+otherConsumed*n(x.generalWaste)/100,base=balloonConsumed+otherConsumed+recoverable+labor+helpers+transport+waste,contingency=x.contingencyType==="Monto"?n(x.contingency):base*n(x.contingency)/100,cost=base+contingency,mathPrice=x.pricing==="Margen"?cost/(1-clamp(x.rate,0,99.9)/100):cost*(1+n(x.rate)/100),round=n(x.rounding),price=round?Math.ceil(mathPrice/round)*round:mathPrice,cash=balloons.reduce((a,r)=>a+r.cash,0)+others.reduce((a,r)=>a+r.cash,0)+recoverCash(x.recoverables)+labor+helpers+transport+waste+contingency;return{balloons,others,balloonConsumed,otherConsumed,materials:balloonConsumed+otherConsumed,recoverable,labor,helpers,transport,waste,contingency,cost,mathPrice,price,cash,profit:price-cost,margin:price?(price-cost)/price*100:0,hours:x.labor.reduce((a,r)=>a+n(r.hours),0)+x.helpers.reduce((a,r)=>a+n(r.hours),0)}}
function recoverCost(r){return r.method==="Amortización"?(n(r.uses)?n(r.purchase)/n(r.uses):0):n(r.cost)}
function recoverCash(rows){return rows.reduce((a,r)=>a+(r.method==="Alquiler externo"?n(r.cost):0),0)}
function expertWarnings(x,c){const a=[];if(!c.labor)a.push("No cargaste mano de obra.");if(!c.transport)a.push("No cargaste traslado.");if(x.recoverables.some(r=>!recoverCost(r)))a.push("Hay recuperables sin costo por uso asignado.");if(x.labor.some(r=>r.name.includes("Montaje")&&n(r.hours))&&!x.labor.some(r=>r.name==="Desmontaje"&&n(r.hours)))a.push("Hay montaje pero no cargaste desmontaje.");if(c.margin<db.settings.minMargin)a.push("El margen queda por debajo del mínimo configurado.");if(c.balloons.some(r=>r.packs&&r.left))a.push("Necesitás comprar paquetes completos aunque uses menos material.");return a}
function renderExpert(){if(!current||current.mode!=="Experto")current=newExpert();const x=current,c=calcExpert(x);app(`<div class="page-head"><div><p class="eyebrow">Modo 2</p><h1>Cálculo experto</h1><p>Desglosá materiales, stock, recuperables y cada etapa del trabajo.</p></div><button class="btn ghost" data-go="home">← Inicio</button></div><div class="workspace"><div class="form-stack">${eventFields(x)}${rowsSection("Globos por tipo",x.balloonRows,"balloonRows",true)}${rowsSection("Otros consumibles y decoración",x.otherRows,"otherRows",false)}${recoverSection(x)}${laborSection(x)}${helperSection(x)}${transportExpert(x)}<div class="section"><header><h2>Desperdicio e imprevistos</h2></header><div class="section-body grid">${field("Desperdicio globos %","balloonWaste",x.balloonWaste)}${field("Desperdicio otros %","generalWaste",x.generalWaste)}${select("Reserva para imprevistos","contingencyType",x.contingencyType,["Porcentaje","Monto"])}${field(x.contingencyType==="Monto"?"Monto":"Porcentaje","contingency",x.contingency)}</div></div><div class="section"><header><h2>Precio de venta</h2></header><div class="section-body grid">${select("Método","pricing",x.pricing,["Recargo","Margen"])}${field("Porcentaje","rate",x.rate)}${select("Redondeo hacia arriba","rounding",String(x.rounding),["0","100","500","1000","5000"])}${field("Seña / reserva %","deposit",x.deposit)}${field("Validez (días)","validity",x.validity)}</div></div>${stockTables(x,c)}${warningSection(expertWarnings(x,c))}</div>${expertResult(x,c)}</div>`)}
function rowsSection(title,rows,key,balloons){return `<div class="section"><header><h2>${title} ${balloons?H("stock"):""}</h2><div class="inline-actions"><button class="btn small secondary" data-from-library="${key}">Desde biblioteca</button><button class="btn small secondary" data-add-row="${key}">+ Agregar</button></div></header><div class="section-body">${rows.length?`<div class="table-wrap"><table><thead><tr><th>Material</th>${balloons?"<th>Tamaño</th><th>Marca / línea</th><th>Color / terminación</th>":""}<th>Usado</th><th>Paquete</th><th>Precio</th><th>Stock</th><th>Consumido</th><th>Compra</th><th></th></tr></thead><tbody>${rows.map((r,i)=>rowHtml(r,i,key,balloons)).join("")}</tbody></table></div>`:`<div class="empty">Agregá ${balloons?"cada combinación de globo":"los insumos de esta decoración"}.</div>`}</div></div>`}
function rowHtml(r,i,key,b){const c=calcRow(r);return `<tr><td><input class="table-input wide" data-row="${key}" data-i="${i}" data-k="name" value="${esc(r.name|| (b?"Globos":"Material"))}"></td>${b?`<td><input class="table-input" data-row="${key}" data-i="${i}" data-k="size" value="${esc(r.size||'12"')}"></td><td><input class="table-input wide" data-row="${key}" data-i="${i}" data-k="brand" value="${esc(r.brand||"")}"></td><td><input class="table-input wide" data-row="${key}" data-i="${i}" data-k="detail" value="${esc(r.detail||"")}"></td>`:""}<td><input class="table-input" type="number" data-row="${key}" data-i="${i}" data-k="used" value="${n(r.used)}"></td><td><input class="table-input" type="number" data-row="${key}" data-i="${i}" data-k="packQty" value="${n(r.packQty)}"></td><td><input class="table-input" type="number" data-row="${key}" data-i="${i}" data-k="packPrice" value="${n(r.packPrice)}"></td><td><input class="table-input" type="number" data-row="${key}" data-i="${i}" data-k="stock" value="${n(r.stock)}"></td><td class="row-total">${money(c.cons)}</td><td class="row-total">${money(c.cash)}</td><td><button class="btn small danger" data-del-row="${key}" data-i="${i}">×</button></td></tr>`}
function recoverSection(x){return `<div class="section"><header><h2>Recuperables ${H("amortization")}</h2><button class="btn small secondary" data-add-recover>+ Agregar</button></header><div class="section-body">${x.recoverables.length?`<div class="table-wrap"><table><thead><tr><th>Elemento</th><th>Método</th><th>Compra</th><th>Usos</th><th>Costo / uso</th><th></th></tr></thead><tbody>${x.recoverables.map((r,i)=>`<tr><td><input class="table-input wide" data-rec="${i}" data-k="name" value="${esc(r.name)}"></td><td><select class="table-input wide" data-rec="${i}" data-k="method">${["Costo fijo por uso","Amortización","Alquiler externo"].map(o=>`<option ${o===r.method?"selected":""}>${o}</option>`).join("")}</select></td><td><input class="table-input" type="number" data-rec="${i}" data-k="purchase" value="${n(r.purchase)}"></td><td><input class="table-input" type="number" data-rec="${i}" data-k="uses" value="${n(r.uses)}"></td><td><input class="table-input" type="number" data-rec="${i}" data-k="cost" value="${n(r.cost)}" ${r.method==="Amortización"?"disabled":""}><div class="row-total">${money(recoverCost(r))}</div></td><td><button class="btn small danger" data-del-rec="${i}">×</button></td></tr>`).join("")}</tbody></table></div>`:`<div class="empty">Estructuras, bases, telas o luces que regresan después del evento.</div>`}</div></div>`}
function laborSection(x){return `<div class="section"><header><h2>Mano de obra ${H("labor")}</h2></header><div class="section-body"><div class="table-wrap"><table><thead><tr><th>Etapa</th><th>Horas</th><th>Valor / hora</th><th>Total</th></tr></thead><tbody>${x.labor.map((r,i)=>`<tr><td>${r.name}</td><td><input class="table-input" type="number" data-labor="${i}" data-k="hours" value="${n(r.hours)}"></td><td><input class="table-input" type="number" data-labor="${i}" data-k="rate" value="${n(r.rate)}"></td><td class="row-total">${money(n(r.hours)*n(r.rate))}</td></tr>`).join("")}</tbody></table></div></div></div>`}
function helperSection(x){return `<div class="section"><header><h2>Ayudantes</h2><button class="btn small secondary" data-add-helper>+ Agregar</button></header><div class="section-body">${x.helpers.length?`<div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Modalidad</th><th>Horas</th><th>Valor / hora</th><th>Pago fijo</th><th></th></tr></thead><tbody>${x.helpers.map((r,i)=>`<tr><td><input class="table-input wide" data-helper="${i}" data-k="name" value="${esc(r.name)}"></td><td><select class="table-input" data-helper="${i}" data-k="type"><option ${r.type==="Por hora"?"selected":""}>Por hora</option><option ${r.type==="Fijo"?"selected":""}>Fijo</option></select></td><td><input class="table-input" type="number" data-helper="${i}" data-k="hours" value="${n(r.hours)}"></td><td><input class="table-input" type="number" data-helper="${i}" data-k="rate" value="${n(r.rate)}"></td><td><input class="table-input" type="number" data-helper="${i}" data-k="fixed" value="${n(r.fixed)}"></td><td><button class="btn small danger" data-del-helper="${i}">×</button></td></tr>`).join("")}</tbody></table></div>`:`<div class="empty">No agregaste ayudantes.</div>`}</div></div>`}
function transportExpert(x){return `<div class="section"><header><h2>Traslado</h2></header><div class="section-body grid">${field("Kilómetros por viaje","km",x.km)}${field("Costo por km","kmCost",x.kmCost)}${field("Cantidad de viajes","trips",x.trips)}${field("Peajes","tolls",x.tolls)}${field("Estacionamiento","parking",x.parking)}${field("Flete","freight",x.freight)}${field("Otros","transportOther",x.transportOther)}</div></div>`}
function stockTables(x,c){const left=[...x.balloonRows.map((r,i)=>({name:`${r.name||"Globos"} ${r.size||""}`,c:c.balloons[i]})),...x.otherRows.map((r,i)=>({name:r.name,c:c.others[i]}))].filter(v=>v.c.left);return `<div class="section"><header><h2>Material que queda en stock</h2></header><div class="section-body">${left.length?`<div class="table-wrap"><table><thead><tr><th>Material</th><th>Cantidad</th><th>Valor</th></tr></thead><tbody>${left.map(v=>`<tr><td>${esc(v.name)}</td><td>${v.c.left}</td><td>${money(v.c.leftValue)}</td></tr>`).join("")}</tbody></table></div>`:`<div class="empty">No hay sobrantes calculados.</div>`}</div></div><div class="section"><header><h2>Material que regresa</h2></header><div class="section-body">${x.recoverables.length?x.recoverables.map(r=>`<span class="status">${esc(r.name||"Recuperable")} · ${money(recoverCost(r))}/uso</span>`).join(" "):`<div class="empty">No hay recuperables cargados.</div>`}</div></div>`}
function expertResult(x,c){return `<aside class="result-panel"><p class="eyebrow" style="color:#d8bd84">Resumen experto</p><h2>${esc(x.name)||"Nuevo trabajo"}</h2>${rr("Materiales consumidos",c.materials)}${rr("Recuperables / uso",c.recoverable)}${rr("Mano de obra",c.labor)}${rr("Ayudantes",c.helpers)}${rr("Traslado",c.transport)}${rr("Desperdicio",c.waste)}${rr("Imprevistos",c.contingency)}${rr("Costo real del evento",c.cost)}<div class="cash-box"><small>DINERO A DESEMBOLSAR ${H("cash")}</small><strong>${money(c.cash)}</strong></div>${rr("Precio matemático",c.mathPrice)}<div class="result-main"><small>Precio comercial sugerido</small><strong>${money(c.price)}</strong></div>${rr("Ganancia",c.profit)}${rr("Margen real",pct(c.margin),true)}<div class="result-actions"><button class="btn primary" data-save>Guardar presupuesto</button><button class="btn secondary" data-client>Ver presupuesto para cliente</button><button class="btn secondary" data-profit-from>Analizar rentabilidad</button>${x.status!=="Cancelado"&&!x.confirmedStock?'<button class="btn secondary" data-confirm>Marcar como confirmado</button>':""}</div></aside>`}
function newProfit(source=null){let cost=0,price=0,hours=0,name="";if(source){const c=source.mode==="Básico"?calcBasic(source):calcExpert(source);cost=c.cost;price=c.price;hours=c.hours;name=source.name}return{name,price,cost,hours,events:1,commissionType:"Porcentaje",commission:0,taxType:"Porcentaje",tax:0,discountType:"Porcentaje",discount:0,commercial:0,contingency:0,market:0,minMargin:db.settings.minMargin}}
function calcProfit(x){const quoted=n(x.price),discount=x.discountType==="Monto"?n(x.discount):quoted*n(x.discount)/100,effective=Math.max(0,quoted-discount),commission=x.commissionType==="Monto"?n(x.commission):effective*n(x.commission)/100,tax=x.taxType==="Monto"?n(x.tax):effective*n(x.tax)/100,net=effective-commission-tax,totalCost=(n(x.cost)+n(x.commercial)+n(x.contingency))*Math.max(1,n(x.events)),profit=net-totalCost,margin=effective?profit/effective*100:0,hourly=n(x.hours)?profit/n(x.hours):0,variable=(x.commissionType==="Porcentaje"?n(x.commission):0)+(x.taxType==="Porcentaje"?n(x.tax):0)+(x.discountType==="Porcentaje"?n(x.discount):0),fixed=totalCost+(x.commissionType==="Monto"?n(x.commission):0)+(x.taxType==="Monto"?n(x.tax):0)+(x.discountType==="Monto"?n(x.discount):0),breakeven=variable<100?fixed/(1-variable/100):0,target=n(x.minMargin),recommended=variable+target<100?fixed/(1-(variable+target)/100):0,diff=recommended-n(x.market);return{quoted,discount,effective,commission,tax,net,totalCost,profit,margin,hourly,breakeven,recommended,diff,diffPct:n(x.market)?diff/n(x.market)*100:0,status:profit<=0?"NO RENTABLE":margin>=target?"RENTABLE":"RENTABILIDAD AJUSTADA"}}
function renderProfit(){if(!current||current.mode!=="Rentabilidad")current={mode:"Rentabilidad",...newProfit()};const x=current,c=calcProfit(x),klass=c.status==="RENTABLE"?"good":c.status.includes("AJUSTADA")?"tight":"bad";app(`<div class="page-head"><div><p class="eyebrow">Modo 2</p><h1>Rentabilidad</h1><p>¿Realmente te conviene aceptar este trabajo por ese precio?</p></div><button class="btn ghost" data-go="home">← Inicio</button></div><div class="workspace"><div class="form-stack"><div class="section"><header><h2>Escenario comercial</h2></header><div class="section-body grid">${field("Trabajo","name",x.name,"text","s6")}${field("Precio publicado / cotizado","price",x.price)}${field("Cantidad de eventos","events",x.events)}${field("Costo real por evento","cost",x.cost)}${field("Horas totales reales","hours",x.hours)}${field("Precio de mercado","market",x.market)}${select("Descuento","discountType",x.discountType,["Porcentaje","Monto"])}${field(x.discountType==="Monto"?"Monto descuento":"Descuento %","discount",x.discount)}${select("Comisión","commissionType",x.commissionType,["Porcentaje","Monto"])}${field(x.commissionType==="Monto"?"Monto comisión":"Comisión %","commission",x.commission)}${select("Impuestos","taxType",x.taxType,["Porcentaje","Monto"])}${field(x.taxType==="Monto"?"Monto impuestos":"Impuestos %","tax",x.tax)}${field("Otros costos comerciales","commercial",x.commercial)}${field("Reserva de imprevistos","contingency",x.contingency)}${field("Margen mínimo deseado %","minMargin",x.minMargin)}</div></div><div class="section"><header><h2>Simulador “¿Qué pasa si...?”</h2></header><div class="section-body">${range("Precio de venta","price",x.price,0,Math.max(100000,n(x.price)*2,10000),500)}${range("Descuento %","discount",x.discount,0,50,1)}${range("Horas trabajadas","hours",x.hours,0,100,1)}${range("Costo real","cost",x.cost,0,Math.max(100000,n(x.cost)*2,10000),500)}${range("Comisión %","commission",x.commission,0,40,1)}</div></div>${warningSection(n(x.market)&&n(x.market)<c.breakeven?["Tu precio de mercado está por debajo del punto de equilibrio."]:[])}</div><aside class="result-panel"><div class="profit-light ${klass}"><small>SEMÁFORO DE RENTABILIDAD</small><strong>${c.status}</strong></div>${rr("Precio cotizado",c.quoted)}${rr("Menos descuento",c.discount)}${rr("Precio efectivo",c.effective)}${rr("Comisiones",c.commission)}${rr("Impuestos",c.tax)}${rr("Ingresos netos",c.net)}${rr("Costos totales",c.totalCost)}<div class="result-main"><small>Ganancia real</small><strong>${money(c.profit)}</strong></div><div class="metric-grid"><div class="metric"><small>Margen real</small><strong>${pct(c.margin)}</strong></div><div class="metric"><small>Ganancia / hora ${H("hourlyProfit")}</small><strong>${money(c.hourly)}</strong></div><div class="metric"><small>Punto de equilibrio ${H("breakeven")}</small><strong>${money(c.breakeven)}</strong></div><div class="metric"><small>Precio mínimo recomendado</small><strong>${money(c.recommended)}</strong></div></div>${n(x.market)?`<div class="cash-box"><small>DIFERENCIA CONTRA MERCADO</small><strong>${money(c.diff)} · ${pct(c.diffPct)}</strong></div>`:""}</aside></div>`)}
function range(label,key,val,min,max,step){return `<div class="range-line"><label>${label}</label><input type="range" min="${min}" max="${max}" step="${step}" value="${n(val)}" data-field="${key}"><input class="table-input" type="number" value="${n(val)}" data-field="${key}"></div>`}
function renderEstimator(){const e=current?.mode==="Estimador"?current:{mode:"Estimador",type:"Guirnalda orgánica",density:"Media",meters:3,width:2,height:2,counts:{}};current=e;const cfg=db.settings.estimator,isWall=e.type==="Pared",base=isWall?n(e.width)*n(e.height)*n(cfg.wallPerM2):n(e.meters)*n(cfg.perMeter)*n(cfg.types[e.type]||1),total=Math.max(0,Math.round(base*n(cfg.density[e.density]||1))),dist=cfg.distribution,keys=Object.keys(dist);let allocated=0;const counts={};keys.forEach((k,i)=>{counts[k]=i===keys.length-1?total-allocated:Math.round(total*n(dist[k])/100);allocated+=counts[k]});for(const k in e.counts)if(e.counts[k]!==undefined)counts[k]=n(e.counts[k]);estimatorResult={total:Object.values(counts).reduce((a,v)=>a+n(v),0),counts};app(`<div class="page-head"><div><p class="eyebrow">Herramienta orientativa</p><h1>Estimador de globos</h1><p>Un punto de partida configurable para planificar cantidades.</p></div><button class="btn ghost" data-go="home">← Inicio</button></div><div class="workspace"><div class="form-stack"><div class="section"><header><h2>Tipo y medida</h2></header><div class="section-body grid">${select("Decoración","type",e.type,["Guirnalda orgánica","Arco orgánico","Medio arco","Arco completo","Columna","Pared","Bouquet","Otro"])}${select("Densidad","density",e.density,["Básica","Media","Abundante"])}${isWall?field("Ancho (m)","width",e.width)+field("Alto (m)","height",e.height):field("Metros lineales","meters",e.meters)}</div></div><div class="section"><header><h2>Distribución sugerida</h2></header><div class="section-body"><div class="table-wrap"><table><thead><tr><th>Tamaño</th><th>Proporción configurada</th><th>Cantidad editable</th></tr></thead><tbody>${keys.map(k=>`<tr><td><b>${k}</b></td><td>${pct(dist[k])}</td><td><input class="table-input" type="number" data-est-count="${k}" value="${counts[k]}"></td></tr>`).join("")}</tbody></table></div></div></div><div class="note"><b>Esta es una estimación inicial.</b> La cantidad real puede variar según técnica, tamaños, estructura, mezcla y estilo de armado. Los parámetros son orientativos y el docente puede modificarlos en Configuración.</div></div><aside class="result-panel"><p class="eyebrow" style="color:#d8bd84">Cantidad inicial</p><div class="est-total" style="color:white">${estimatorResult.total}</div><p>globos estimados</p>${keys.map(k=>rr(k,counts[k],true)).join("")}<div class="result-actions"><button class="btn primary" data-send-basic>Enviar a Armado de presupuesto</button></div></aside></div>`)}
function newQuick(){return{...newBasic(),quick:true,meters:3,baseSize:'9"',cluster:3,quickWaste:10}}
function calcQuick(x){const is12=x.baseSize==='12"',meters=Math.max(0,n(x.meters)),groupsPerMeter=is12?5:7,trioGroups=Math.ceil(meters*groupsPerMeter),quartetGroups=Math.ceil(meters*groupsPerMeter),trio=trioGroups*3,quartet=quartetGroups*4,cluster=n(x.cluster)===4?4:3,clusters=cluster===4?quartetGroups:trioGroups,design=cluster===4?quartet:trio,perMeter=is12?(cluster===4?20:15):(cluster===4?28:21),reserve=Math.ceil(design*n(x.quickWaste)/100),total=design+reserve;return{groupsPerMeter,trioGroups,quartetGroups,clusters,trio,quartet,cluster,design,reserve,total,perMeter}}
function renderQuick(){if(!current||!current.quick)current=newQuick();const x=current,c=calcQuick(x),groupName=c.cluster===4?"cuartetos":"tríos";app(`<div class="page-head"><div><p class="eyebrow">Cantidad para el armado</p><h1>Calculadora por metros</h1><p>Elegí el globo base y calculá el armado en tríos o cuartetos.</p></div><button class="btn ghost" data-go="home">← Inicio</button></div><div class="workspace"><div class="form-stack"><div class="section"><header><h2>Cómo vas a armarlo</h2></header><div class="section-body grid">${field("Metros lineales del armado","meters",x.meters)}${select("Globo base","baseSize",x.baseSize,['9"','12"'])}${select("Tipo de agrupación","cluster",String(x.cluster),["3","4"])}${field("Roturas y reserva %","quickWaste",x.quickWaste)}</div></div><div class="section"><header><h2>Comparación del armado</h2></header><div class="section-body"><div class="metric-grid"><div class="metric"><small>Armado en tríos</small><strong>${c.trio} globos</strong><span>${c.trioGroups} tríos</span></div><div class="metric"><small>Armado en cuartetos</small><strong>${c.quartet} globos</strong><span>${c.quartetGroups} cuartetos</span></div></div></div></div><div class="section"><header><h2>Cómo se calcula</h2></header><div class="section-body"><div class="note"><b>Rendimiento utilizado:</b> por cada metro, los globos de 12 pulgadas usan 15 unidades en tríos o 20 en cuartetos; los de 9 pulgadas usan 21 unidades en tríos o 28 en cuartetos. En medidas decimales se redondea hacia arriba para completar el último grupo.</div></div></div></div><aside class="result-panel"><p class="eyebrow" style="color:#d8bd84">ARMADO SELECCIONADO</p><h2>Base de ${esc(x.baseSize)} · ${groupName}</h2><div class="metric-grid"><div class="metric"><small>Grupos necesarios</small><strong>${c.clusters}</strong></div><div class="metric"><small>Globos sin reserva</small><strong>${c.design}</strong></div></div>${rr("Rendimiento seleccionado",c.perMeter+" globos por metro",true)}${rr("Reserva por roturas",c.reserve+" globos",true)}<div class="result-main"><small>Total a preparar</small><strong>${c.total} globos</strong></div><p style="font-size:.82rem;color:#c5d4d7;line-height:1.5">Para ${n(x.meters).toLocaleString("es-AR")} m necesitás ${c.clusters} ${groupName}, usando ${c.design} globos en el armado.</p></aside></div>`)}
function renderHome(){current=null;app(`<section class="hero"><p class="eyebrow">Instituto Bruner × Happy Deco</p><h1>Presupuestá con claridad.<br>Trabajá con rentabilidad.</h1><p>Una herramienta profesional que diferencia lo que consumís, lo que necesitás comprar y lo que vuelve con vos después del evento.</p></section><section class="mode-grid"><button class="mode-card" data-go="quick"><span class="num">⚡</span><h2>Cálculo Rápido</h2><p>Metros, pulgadas y armado en tríos o cuartetos.</p></button><button class="mode-card" data-go="basic"><span class="num">01</span><h2>Armado de presupuesto</h2><p>Calculá bolsas por color, costos y precio de venta.</p></button><button class="mode-card" data-go="profit"><span class="num">02</span><h2>Rentabilidad</h2><p>Analizá si realmente te conviene aceptar el trabajo.</p></button></section><section class="quick-grid"><button class="quick" data-go="estimator"><b>Estimador de Globos →</b><small>Calculá una cantidad inicial según medida y densidad.</small></button><button class="quick secondary" data-go="budget"><b>Presupuesto</b><small>${db.budgets.length} cálculos guardados</small></button><button class="quick secondary" data-go="library"><b>Biblioteca</b><small>${db.materials.length} materiales</small></button><button class="quick secondary" data-go="manual"><b>Manual de uso</b><small>Aprendé la herramienta paso a paso.</small></button></section>`)}
function renderBudget(){if(current&&["Básico","Experto"].includes(current.mode)){const x=current,c=x.mode==="Básico"?calcBasic(x):calcExpert(x);app(`<div class="page-head"><div><p class="eyebrow">Datos para el cliente</p><h1>${esc(x.name)||"Presupuesto"}</h1><p>Completá los datos del evento, guardá y generá la propuesta.</p></div><button class="btn ghost" data-budget-list>← Mis presupuestos</button></div><div class="workspace"><div class="form-stack">${eventFields(x)}<div class="section"><header><h2>Acciones</h2></header><div class="section-body inline-actions"><button class="btn primary" data-save>Guardar cambios</button><button class="btn secondary" data-client>Ver presupuesto para cliente</button>${x.mode==="Experto"&&!x.confirmedStock?'<button class="btn secondary" data-confirm>Confirmar y descontar stock</button>':''}</div></div></div><aside class="result-panel"><p class="eyebrow" style="color:#d8bd84">RESUMEN</p><h2>${esc(modeLabel(x.mode))}</h2>${rr("Costo real",c.cost)}<div class="result-main"><small>Precio final</small><strong>${money(c.price)}</strong></div>${rr("Ganancia estimada",c.profit)}${rr("Margen",pct(c.margin),true)}</aside></div>`);return}current=null;const list=db.budgets;app(`<div class="page-head"><div><p class="eyebrow">Trabajos guardados</p><h1>Mis presupuestos</h1><p>Elegí uno para completar los datos del cliente o imprimirlo.</p></div><button class="btn primary" data-new-basic>+ Nuevo presupuesto</button></div><div class="history-grid">${list.length?list.map(b=>{const c=b.mode==="Básico"?calcBasic(b):calcExpert(b);return `<article class="history-card"><div><div class="meta"><span class="status ${String(b.status||'Borrador').toLowerCase()}">${esc(b.status||"Borrador")}</span><span>${esc(modeLabel(b.mode))}</span></div><h3>${esc(b.name||"Trabajo sin nombre")}</h3><div class="meta"><span>${esc(b.client||"Sin cliente")}</span><span>${esc(b.eventDate||"")}</span></div></div><div><div class="price-pair"><strong>${money(c.price)}</strong><small>Costo ${money(c.cost)}</small></div><button class="btn small secondary" data-budget-meta="${b.id}">Completar datos</button></div></article>`}).join(""):'<div class="section empty">Todavía no guardaste presupuestos.</div>'}</div>`) }
function renderHistory(){const q=current?.mode==="History"?current.q:"";current={mode:"History",q};const list=db.budgets.filter(b=>[b.client,b.name,b.eventDate].join(" ").toLowerCase().includes(q.toLowerCase()));app(`<div class="page-head"><div><p class="eyebrow">Historial local</p><h1>Mis presupuestos</h1><p>Se guardan únicamente en este navegador.</p></div><div class="toolbar"><input class="search" data-history-search placeholder="Buscar cliente, trabajo o fecha" value="${esc(q)}"><button class="btn primary" data-new-basic>+ Nuevo</button></div></div><div class="history-grid">${list.length?list.map(b=>{const c=b.mode==="Básico"?calcBasic(b):calcExpert(b);return `<article class="history-card"><div><div class="meta"><span class="status ${b.status?.toLowerCase()}">${esc(b.status||"Borrador")}</span><span>${esc(modeLabel(b.mode))}</span><span>${esc(b.eventDate||new Date(b.created).toLocaleDateString("es-AR"))}</span></div><h3>${esc(b.name||"Trabajo sin nombre")}</h3><div class="meta"><span>${esc(b.client||"Sin cliente")}</span><span>${esc(b.type||"")}</span><span>Margen ${pct(c.margin)}</span></div></div><div><div class="price-pair"><strong>${money(c.price)}</strong><small>Costo ${money(c.cost)}</small></div><div class="inline-actions" style="margin-top:8px"><button class="btn small secondary" data-open-budget="${b.id}">Abrir</button><button class="btn small ghost" data-dup-budget="${b.id}">Duplicar</button><button class="btn small danger" data-del-budget="${b.id}">Eliminar</button></div></div></article>`}).join(""):`<div class="section empty">No hay presupuestos que coincidan.</div>`}</div>`)}
function renderLibrary(){const cats=["Todos","Globos","Consumibles","Decoración","Recuperables"],list=db.materials.filter(m=>activeLibrary==="Todos"||m.category===activeLibrary);app(`<div class="page-head"><div><p class="eyebrow">Base editable</p><h1>Biblioteca de materiales</h1><p>Precios y stock disponibles para reutilizar en tus presupuestos.</p></div><button class="btn primary" data-add-material>+ Nuevo material</button></div><div class="tabs">${cats.map(c=>`<button data-lib-cat="${c}" class="${c===activeLibrary?"active":""}">${c}</button>`).join("")}</div><div id="materialEditor"></div><div class="library-grid">${list.length?list.map(m=>`<article class="material-card"><div><div class="meta"><span>${esc(m.category)}</span><span>${esc(m.type||"")}</span></div><h3>${esc(m.name)}</h3><div class="meta"><span>${esc(m.brand||"")} ${esc(m.size||"")}</span><span>Paquete: ${n(m.packQty)}</span><span>Stock: ${n(m.stock)}</span></div></div><div><div class="price-pair"><strong>${money(m.packPrice||m.cost)}</strong><small>${m.category==="Recuperables"?"Costo / compra":"Precio paquete"}</small></div><div class="inline-actions" style="margin-top:8px"><button class="btn small secondary" data-edit-material="${m.id}">Editar</button><button class="btn small ghost" data-dup-material="${m.id}">Duplicar</button><button class="btn small danger" data-del-material="${m.id}">Eliminar</button></div></div></article>`).join(""):`<div class="section empty">Todavía no hay materiales en esta categoría.</div>`}</div>`)}
function materialEditor(m={id:uid(),category:"Globos",name:"",brand:"",size:'12"',detail:"Standard",packQty:100,packPrice:0,stock:0,type:"Sobrante reutilizable",cost:0}){return `<div class="section" style="margin-bottom:16px"><header><h2>${db.materials.some(x=>x.id===m.id)?"Editar":"Nuevo"} material</h2><button class="btn small ghost" data-cancel-material>Cancelar</button></header><div class="section-body grid">${select("Categoría","category",m.category,["Globos","Consumibles","Decoración","Recuperables"])}${field("Nombre","name",m.name,"text")}${select("Clasificación","type",m.type,["Consumible","Sobrante reutilizable","Recuperable"])}${field("Marca","brand",m.brand,"text")}${field("Tamaño","size",m.size,"text")}${field("Color / terminación","detail",m.detail,"text")}${field("Cantidad por paquete","packQty",m.packQty)}${field("Precio paquete / compra","packPrice",m.packPrice)}${field("Stock actual","stock",m.stock)}<div class="field s12"><button class="btn primary" data-save-material data-mid="${m.id}">Guardar material</button></div></div></div>`}
function renderSettings(){const s=db.settings,e=s.estimator;app(`<div class="page-head"><div><p class="eyebrow">Preferencias del taller</p><h1>Configuración</h1><p>Todos los valores pueden adaptarse a tu moneda, técnica y forma de trabajar.</p></div><button class="btn primary" data-save-settings>Guardar cambios</button></div><div class="form-stack"><div class="section"><header><h2>Valores generales</h2></header><div class="section-body grid">${select("Moneda","currency",s.currency,["$","USD","€","Otro"])}${field("Símbolo personalizado","customCurrency",s.customCurrency,"text")}${field("Valor hora habitual","hourly",s.hourly)}${field("Costo por kilómetro","km",s.km)}${field("Margen mínimo %","minMargin",s.minMargin)}${field("Margen objetivo %","targetMargin",s.targetMargin)}${field("Desperdicio habitual %","waste",s.waste)}${field("Imprevistos %","contingency",s.contingency)}${select("Redondeo comercial","rounding",String(s.rounding),["0","100","500","1000","5000"])}</div></div><div class="section"><header><h2>Parámetros del Estimador</h2></header><div class="section-body"><div class="note" style="margin-bottom:16px">Parámetros orientativos, no reglas universales. Ajustalos según la técnica enseñada y registrá tus propios rendimientos reales.</div><div class="grid">${field("Globos por metro","estimator.perMeter",e.perMeter)}${field("Globos por m² de pared","estimator.wallPerM2",e.wallPerM2)}${Object.entries(e.density).map(([k,v])=>field(`Multiplicador ${k}`,`estimator.density.${k}`,v)).join("")}</div><h3>Distribución por tamaño (%)</h3><div class="grid">${Object.entries(e.distribution).map(([k,v])=>field(k,`estimator.distribution.${k}`,v)).join("")}</div><h3>Multiplicadores por tipo</h3><div class="grid">${Object.entries(e.types).map(([k,v])=>field(k,`estimator.types.${k}`,v)).join("")}</div></div></div><div class="section"><header><h2>Datos</h2></header><div class="section-body inline-actions"><button class="btn secondary" data-export>Exportar copia de seguridad</button><label class="btn ghost">Importar<input type="file" accept="application/json" data-import hidden></label><button class="btn danger" data-reset>Restablecer configuración</button></div></div></div>`)}
function renderManual(){app(`<div class="page-head"><div><p class="eyebrow">Aprendé mientras presupuestás</p><h1>Manual de uso</h1><p>Un recorrido práctico para pasar de la idea al presupuesto final sin olvidar costos.</p></div><button class="btn primary" data-go="basic">Crear mi primer presupuesto</button></div><section class="manual-intro"><div><h2>Antes de empezar</h2><p>Configurá tus valores habituales y cargá los materiales que usás con frecuencia. La aplicación guarda todo en este dispositivo.</p></div><div class="manual-brand"><img src="assets/instituto-bruner.png" alt="Instituto Bruner"><img src="assets/happy-deco.png" alt="Happy Deco"></div></section><div class="manual-steps"><article class="manual-step"><span class="step-num">1</span><h2>Configurá tu forma de trabajar</h2><p>Entrá en <b>Configuración</b> y definí moneda, valor por hora, costo por kilómetro, margen mínimo, desperdicio e imprevistos.</p><button class="btn small secondary" data-go="settings">Ir a Configuración</button></article><article class="manual-step"><span class="step-num">2</span><h2>Armá tu biblioteca</h2><p>Cargá globos, consumibles, decoración y recuperables. Indicá precio, cantidad por paquete y stock actual. Después podrás reutilizarlos en cada presupuesto.</p><button class="btn small secondary" data-go="library">Ir a Materiales</button></article><article class="manual-step"><span class="step-num">3</span><h2>Estimá los globos</h2><p>Si todavía no conocés la cantidad, elegí tipo, medida y densidad. Revisá la distribución por tamaño y modificá cualquier valor antes de enviarlo al cálculo.</p><button class="btn small secondary" data-go="estimator">Abrir Estimador</button></article><article class="manual-step"><span class="step-num">4</span><h2>Armá el presupuesto</h2><p>Escribí el nombre y la cantidad de globos de cada color. Luego cargá el precio y contenido de cada bolsa, las horas de trabajo, el traslado y los demás insumos.</p></article><article class="manual-step"><span class="step-num">5</span><h2>Cargá el trabajo completo</h2><p>Completá cliente, evento y materiales. Sumá preparación, montaje y desmontaje. Cargá traslado, desperdicio e imprevistos. Mirá las advertencias: enseñan qué podrías estar olvidando.</p></article><article class="manual-step"><span class="step-num">6</span><h2>Definí el precio</h2><p>Elegí <b>recargo</b> si querés sumar un porcentaje al costo o <b>margen</b> si querés que la ganancia represente una parte del precio final.</p></article><article class="manual-step"><span class="step-num">7</span><h2>Comprobá la rentabilidad</h2><p>Enviá el presupuesto a Rentabilidad. Probá precio, descuento, comisiones, impuestos y horas. El semáforo te dirá si llegás al margen mínimo configurado.</p><button class="btn small secondary" data-go="profit">Analizar rentabilidad</button></article><article class="manual-step"><span class="step-num">8</span><h2>Guardá, enviá y confirmá</h2><p>Guardá el presupuesto, abrí la vista para cliente e imprimila como PDF. Solo al confirmar el trabajo se descuenta stock, evitando movimientos por presupuestos que todavía no fueron aceptados.</p></article></div><section class="section" style="margin-top:18px"><header><h2>Cuatro conceptos que no hay que mezclar</h2></header><div class="section-body concept-grid"><div class="concept"><b>Costo consumido</b>Valor de lo que realmente usaste, aunque ya estuviera en stock.</div><div class="concept"><b>Desembolso</b>Dinero que necesitás sacar hoy para comprar lo que falta.</div><div class="concept"><b>Sobrante</b>Material comprado que queda disponible y conserva valor.</div><div class="concept"><b>Recuperable</b>Elemento que regresa y se imputa por uso, amortización o alquiler.</div><div class="concept"><b>Recargo</b>Ganancia calculada como porcentaje del costo.</div><div class="concept"><b>Margen</b>Ganancia calculada como porcentaje del precio cobrado.</div></div></section><div class="manual-tip"><b>Consejo del taller:</b> después de cada evento compará las horas y materiales estimados con los reales. Esa información te permitirá mejorar tus parámetros y presupuestar con cada vez más precisión.</div>`)}
function app(html){const root=$("#app");root.dataset.route=route;root.innerHTML=html;$$('[data-go]').forEach(b=>b.classList.toggle("active",b.dataset.go===route));root.focus({preventScroll:true})}
function render(){({home:renderHome,quick:renderQuick,basic:renderBasic,profit:renderProfit,estimator:renderEstimator,budget:renderBudget,history:renderHistory,library:renderLibrary,manual:renderManual,settings:renderSettings}[route]||renderHome)()}
function navigate(r){route=r;current=null;$("#mainNav").classList.remove("open");render();scrollTo(0,0)}
function saveBudget(){if(!["Básico","Experto"].includes(current?.mode))return;const i=db.budgets.findIndex(b=>b.id===current.id);if(i<0)db.budgets.unshift(structuredClone(current));else db.budgets[i]=structuredClone(current);persist();toast("Presupuesto guardado")}
function openClient(){if(!current)return;const c=current.mode==="Básico"?calcBasic(current):calcExpert(current),deposit=c.price*n(current.deposit||30)/100;$("#clientView").innerHTML=`<div class="client-sheet"><div class="client-logo">Propuesta de decoración</div><h1>${esc(current.name||"Decoración con globos")}</h1><p>Preparado para <b>${esc(current.client||"Cliente")}</b></p><div class="grid"><div class="field s6"><label>Fecha</label><div>${esc(current.eventDate||"A coordinar")}</div></div><div class="field s6"><label>Lugar</label><div>${esc(current.place||"A coordinar")}</div></div><div class="field s6"><label>Tipo</label><div>${esc(current.type||"")}</div></div><div class="field s6"><label>Cantidad</label><div>${n(current.quantity)||1}</div></div></div><h3>Servicios incluidos</h3><p>Diseño y preparación de la decoración. Montaje: ${hasSetup(current)?"Sí":"A coordinar"}. Desmontaje: ${hasTeardown(current)?"Sí":"No incluido"}.</p><p>${esc(current.notes||"")}</p><div class="client-total"><span>Precio final</span><strong>${money(c.price)}</strong></div><p><b>Seña / reserva:</b> ${money(deposit)}<br><b>Saldo:</b> ${money(c.price-deposit)}<br><b>Validez:</b> ${n(current.validity||10)} días.</p></div>`;$("#clientDialog").showModal()}
function hasSetup(x){return x.mode==="Básico"?n(x.setupHours)>0:x.labor?.some(r=>r.name.includes("Montaje")&&n(r.hours))}function hasTeardown(x){return x.mode==="Básico"?n(x.teardownHours)>0:x.labor?.some(r=>r.name==="Desmontaje"&&n(r.hours))}
function confirmStock(){if(current.mode!=="Experto")return;const use=current.balloonRows.map((r,i)=>({r,c:calcRow(r),lib:db.materials.find(m=>m.id===r.materialId)})).filter(x=>x.lib&&x.c.stockUsed);$("#confirmStock").innerHTML=use.length?`<p>Se descontará del stock:</p><ul>${use.map(x=>`<li>${esc(x.lib.name)}: ${x.c.stockUsed}</li>`).join("")}</ul>`:"<p>No hay filas vinculadas a la biblioteca con stock disponible. El trabajo quedará confirmado sin descontar materiales.</p>";$("#confirmDialog").dataset.budget=current.id;$("#confirmDialog").showModal()}
document.addEventListener("click",e=>{const b=e.target.closest("button,[data-go],label");if(!b)return;if(b.dataset.go)return navigate(b.dataset.go);if(b.id==="menuBtn")return $("#mainNav").classList.toggle("open");if(b.dataset.close!==undefined)return b.closest("dialog").close();if(b.dataset.help){const h=help[b.dataset.help];$("#helpTitle").textContent=h[0];$("#helpText").textContent=h[1];return $("#helpDialog").showModal()}if(b.dataset.set){current[b.dataset.set]=b.dataset.value;return render()}if(b.dataset.addExtra!==undefined){current.extras.push({name:"",amount:0});return render()}if(b.dataset.delExtra!==undefined){current.extras.splice(+b.dataset.delExtra,1);return render()}if(b.dataset.addRow){current[b.dataset.addRow].push({name:b.dataset.addRow==="balloonRows"?"Globos":"Material",size:'12"',brand:"",detail:"Standard",used:0,packQty:100,packPrice:0,stock:0});return render()}if(b.dataset.delRow){current[b.dataset.delRow].splice(+b.dataset.i,1);return render()}if(b.dataset.addRecover!==undefined){current.recoverables.push({name:"Estructura",method:"Costo fijo por uso",purchase:0,uses:20,cost:0});return render()}if(b.dataset.delRec!==undefined){current.recoverables.splice(+b.dataset.delRec,1);return render()}if(b.dataset.addHelper!==undefined){current.helpers.push({name:"",type:"Por hora",hours:0,rate:db.settings.hourly,fixed:0});return render()}if(b.dataset.delHelper!==undefined){current.helpers.splice(+b.dataset.delHelper,1);return render()}if(b.dataset.save!==undefined)return saveBudget();if(b.dataset.client!==undefined)return openClient();if(b.dataset.profitFrom!==undefined){const src=structuredClone(current);route="profit";current={mode:"Rentabilidad",...newProfit(src)};return render()}if(b.dataset.goEstimator!==undefined){route="estimator";current={mode:"Estimador",type:current.type==="Pared de globos"?"Pared":"Guirnalda orgánica",density:"Media",meters:3,width:2,height:2,counts:{}};return render()}if(b.dataset.sendBasic!==undefined){const total=estimatorResult.total;current=newBasic();current.balloons=total;current.colorRows=[{name:"Color 1",qty:total}];route="basic";return render()}if(b.dataset.newBasic!==undefined){current=newBasic();route="basic";return render()}if(b.dataset.openBudget){current=structuredClone(db.budgets.find(x=>x.id===b.dataset.openBudget));route=current.mode==="Básico"?"basic":"budget";return render()}if(b.dataset.dupBudget){const x=structuredClone(db.budgets.find(x=>x.id===b.dataset.dupBudget));x.id=uid();x.name=(x.name||"Trabajo")+" (copia)";x.created=new Date().toISOString();x.status="Borrador";x.confirmedStock=false;db.budgets.unshift(x);persist();return render()}if(b.dataset.delBudget){if(confirm("¿Eliminar este presupuesto?")){db.budgets=db.budgets.filter(x=>x.id!==b.dataset.delBudget);persist();render()}return}if(b.dataset.libCat){activeLibrary=b.dataset.libCat;return render()}if(b.dataset.addMaterial!==undefined)return $("#materialEditor").innerHTML=materialEditor();if(b.dataset.editMaterial)return $("#materialEditor").innerHTML=materialEditor(structuredClone(db.materials.find(x=>x.id===b.dataset.editMaterial)));if(b.dataset.dupMaterial){const x=structuredClone(db.materials.find(m=>m.id===b.dataset.dupMaterial));x.id=uid();x.name+=" (copia)";db.materials.unshift(x);persist();return render()}if(b.dataset.delMaterial){if(confirm("¿Eliminar este material?")){db.materials=db.materials.filter(x=>x.id!==b.dataset.delMaterial);persist();render()}return}if(b.dataset.cancelMaterial!==undefined)return $("#materialEditor").innerHTML="";if(b.dataset.saveMaterial!==undefined){const box=b.closest(".section"),m={id:b.dataset.mid};$$('[data-field]',box).forEach(i=>m[i.dataset.field]=i.type==="number"?n(i.value):i.value);const idx=db.materials.findIndex(x=>x.id===m.id);if(idx<0)db.materials.unshift(m);else db.materials[idx]=m;persist();toast("Material guardado");return render()}if(b.dataset.saveSettings!==undefined){persist();toast("Configuración guardada");return render()}if(b.dataset.export!==undefined){const blob=new Blob([JSON.stringify(db,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="globologia-copia-seguridad.json";a.click();URL.revokeObjectURL(a.href);return}if(b.dataset.reset!==undefined){if(confirm("¿Restablecer la configuración? Los presupuestos y materiales se conservarán.")){db.settings=structuredClone(defaults.settings);persist();render()}return}if(b.dataset.confirm!==undefined)return confirmStock();if(b.id==="applyStock"){if(current.confirmedStock)return;current.balloonRows.forEach(r=>{const m=db.materials.find(x=>x.id===r.materialId);if(m)m.stock=Math.max(0,n(m.stock)-Math.min(n(r.used),n(m.stock)))});current.status="Confirmado";current.confirmedStock=true;saveBudget();$("#confirmDialog").close();return render()}if(b.id==="printClient")return print()});
document.addEventListener("change",e=>{const t=e.target;if(t.matches("[data-import]"))return;if(t.dataset.historySearch!==undefined){current.q=t.value;return renderHistory()}if(t.dataset.field!==undefined){setPath(route==="settings"?db.settings:current,t.dataset.field,t.type==="number"||t.type==="range"?n(t.value):t.value);if(route==="settings")persist();return render()}if(t.dataset.colorRow!==undefined){current.colorRows[+t.dataset.colorRow][t.dataset.k]=t.dataset.k==="qty"?Math.max(0,Math.ceil(n(t.value))):t.value;return render()}if(t.dataset.extra!==undefined){current.extras[+t.dataset.extra][t.dataset.k]=t.type==="number"?n(t.value):t.value;return render()}if(t.dataset.row){current[t.dataset.row][+t.dataset.i][t.dataset.k]=t.type==="number"?n(t.value):t.value;return render()}if(t.dataset.rec!==undefined){current.recoverables[+t.dataset.rec][t.dataset.k]=t.type==="number"?n(t.value):t.value;return render()}if(t.dataset.labor!==undefined){current.labor[+t.dataset.labor][t.dataset.k]=n(t.value);return render()}if(t.dataset.helper!==undefined){current.helpers[+t.dataset.helper][t.dataset.k]=t.type==="number"?n(t.value):t.value;return render()}if(t.dataset.estCount){current.counts[t.dataset.estCount]=n(t.value);return render()}});
document.addEventListener("input",e=>{const t=e.target;if(t.dataset.field!==undefined){setPath(route==="settings"?db.settings:current,t.dataset.field,t.type==="number"||t.type==="range"?n(t.value):t.value);if(t.type==="range")render();return}if(t.dataset.colorRow!==undefined){current.colorRows[+t.dataset.colorRow][t.dataset.k]=t.dataset.k==="qty"?Math.max(0,Math.ceil(n(t.value))):t.value;return}if(t.dataset.extra!==undefined)current.extras[+t.dataset.extra][t.dataset.k]=t.type==="number"?n(t.value):t.value;if(t.dataset.row)current[t.dataset.row][+t.dataset.i][t.dataset.k]=t.type==="number"?n(t.value):t.value;if(t.dataset.rec!==undefined)current.recoverables[+t.dataset.rec][t.dataset.k]=t.type==="number"?n(t.value):t.value;if(t.dataset.labor!==undefined)current.labor[+t.dataset.labor][t.dataset.k]=n(t.value);if(t.dataset.helper!==undefined)current.helpers[+t.dataset.helper][t.dataset.k]=t.type==="number"?n(t.value):t.value;if(t.dataset.estCount)current.counts[t.dataset.estCount]=n(t.value)});
document.addEventListener("change",e=>{if(e.target.matches("[data-import]")){const f=e.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{try{db=merge(structuredClone(defaults),JSON.parse(rd.result));persist();toast("Copia importada");render()}catch{alert("El archivo no es una copia válida.")}};rd.readAsText(f)}});
document.addEventListener("click",e=>{const edit=e.target.closest("[data-budget-meta]"),back=e.target.closest("[data-budget-list]");if(edit){current=structuredClone(db.budgets.find(b=>b.id===edit.dataset.budgetMeta));route="budget";render()}if(back){current=null;route="budget";render()}});
function setPath(o,path,val){const p=path.split(".");while(p.length>1)o=o[p.shift()];o[p[0]]=val}
document.addEventListener("click",e=>{const b=e.target.closest("[data-from-library]");if(!b)return;const balloons=b.dataset.fromLibrary==="balloonRows",items=db.materials.filter(m=>balloons?m.category==="Globos":["Consumibles","Decoración"].includes(m.category));if(!items.length){toast("No hay materiales compatibles en la biblioteca");return}const answer=prompt("Elegí un material:\n"+items.map((m,i)=>`${i+1}. ${m.name}`).join("\n"),"1"),m=items[n(answer)-1];if(!m)return;current[b.dataset.fromLibrary].push({materialId:m.id,name:m.name,size:m.size||"",brand:m.brand||"",detail:m.detail||"",used:0,packQty:n(m.packQty)||1,packPrice:n(m.packPrice),stock:n(m.stock)});render()});
window.__globologiaTest={calcBasic,calcExpert,calcProfit,calcQuick,newBasic,newExpert,newQuick};
render();


